import React, { useState, useEffect } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { useNavigate, useLocation } from 'react-router-dom';
import { RootState } from '../store';
import { setSearchParams } from '../store/slices/flightSlice';
import EmiratesHeader from '../components/Layout/EmiratesHeader';
import { 
  PaperAirplaneIcon,
  ClockIcon,
  UserGroupIcon,
  CheckCircleIcon,
  XMarkIcon,
  AdjustmentsHorizontalIcon,
  ArrowRightIcon
} from '@heroicons/react/24/outline';
import { cities } from '../data/cities';
import CustomSelect from '../components/CustomSelect/CustomSelect';
import { useLanguage } from '../contexts/LanguageContext';
import { checkAvailability, FlightAvailability, filterListedNiraFlights, getFlightSaleState, getFlightSaleCopy, FlightSaleState, isFlightSearchLimitError } from '../services/niraApi';

interface Flight {
  id: string;
  airline: string;
  flightNumber: string;
  origin: string;
  destination: string;
  departureTime: string;
  arrivalTime: string;
  duration: string;
  price: number;
  availableSeats: number;
  class: 'economy' | 'business' | 'first';
  stops: number;
  originalData: FlightAvailability;
  saleState: FlightSaleState;
  canBook: boolean;
  // فیلدهای جدید برای اطلاعات لحظه‌ای
  actualDepartureTime?: string;
  actualArrivalTime?: string;
  delayMinutes?: number;
  departureGate?: string;
  arrivalGate?: string;
}

const FlightResultsPage: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const dispatch = useDispatch();
  const searchParamsFromStore = useSelector((state: RootState) => state.flight.searchParams);
  const { t, language } = useLanguage();
  
  // Get searchParams from location state (if coming from map) or Redux store (if coming from homepage)
  const searchParams = (location.state as any)?.searchParams || searchParamsFromStore;
  
  const [flights, setFlights] = useState<Flight[]>([]);
  const [loading, setLoading] = useState(true);
  const [limitMessage, setLimitMessage] = useState('');
  const [sortBy, setSortBy] = useState<'price' | 'duration' | 'departure'>('price');
  const [filterStops, setFilterStops] = useState<'all' | 'direct' | 'one'>('all');

  // Save searchParams to Redux if coming from location state
  useEffect(() => {
    if ((location.state as any)?.searchParams) {
      dispatch(setSearchParams((location.state as any).searchParams));
    }
  }, [location.state, dispatch]);

  useEffect(() => {
    const fetchFlights = async () => {
      if (!searchParams) {
        setLoading(false);
        return;
      }

      try {
        setLoading(true);
        setLimitMessage('');
        
        // Get passenger counts
        const passengers = typeof searchParams.passengers === 'object' 
          ? searchParams.passengers 
          : { adults: 1, children: 0, infants: 0 };

        // Call NIRA API
        const availableFlights = await checkAvailability({
          origin: searchParams.origin,
          destination: searchParams.destination,
          departure_date: searchParams.departureDate,
          round_trip: searchParams.tripType === 'roundtrip',
          return_date: searchParams.returnDate,
          adult_qty: passengers.adults,
          child_qty: passengers.children,
          infant_qty: passengers.infants,
        });

        // Show every Nira flight for this OD+date (including cancelled / schedule-only)
        const listedFlights = filterListedNiraFlights(availableFlights);

        const convertedFlights: Flight[] = listedFlights.flatMap((flight, index) => {
          const departureDateTime = new Date(flight.DepartureDateTime);
          const arrivalDateTime = new Date(flight.ArrivalDateTime);
          const durationMs = arrivalDateTime.getTime() - departureDateTime.getTime();
          const hours = Math.floor(durationMs / (1000 * 60 * 60));
          const minutes = Math.floor((durationMs % (1000 * 60 * 60)) / (1000 * 60));
          const duration = `${hours}h ${minutes}m`;
          const timeOpts: Intl.DateTimeFormatOptions = { hour: '2-digit', minute: '2-digit', hour12: false };
          const classes = Array.isArray(flight.ClassStatus) ? flight.ClassStatus : [];

          const toCard = (classStatus: (typeof classes)[number] | null, classIndex: number): Flight => {
            const saleState = getFlightSaleState(flight, classStatus);
            let flightClass: 'economy' | 'business' | 'first' = 'economy';
            const cabin = (classStatus?.CabinClass || '').toLowerCase();
            if (cabin.includes('business')) flightClass = 'business';
            else if (cabin.includes('first')) flightClass = 'first';

            return {
              id: `${flight.FlightNo}-${index}-${classIndex}`,
              airline: flight.AirLineCode || 'NSN',
              flightNumber: flight.FlightNo,
              origin: flight.Origin,
              destination: flight.Destination,
              departureTime: departureDateTime.toLocaleTimeString('en-US', timeOpts),
              arrivalTime: arrivalDateTime.toLocaleTimeString('en-US', timeOpts),
              duration,
              price: Number(classStatus?.TotalPrice ?? 0),
              availableSeats: saleState === 'bookable' ? 10 : 0,
              class: flightClass,
              stops: flight.Stops || 0,
              saleState,
              canBook: saleState === 'bookable',
              actualDepartureTime: flight.ActualDepartureDateTime
                ? new Date(flight.ActualDepartureDateTime).toLocaleTimeString('en-US', timeOpts)
                : undefined,
              actualArrivalTime: flight.ActualArrivalDateTime
                ? new Date(flight.ActualArrivalDateTime).toLocaleTimeString('en-US', timeOpts)
                : undefined,
              delayMinutes: flight.DelayMinutes,
              departureGate: flight.DepartureGate,
              arrivalGate: flight.ArrivalGate,
              originalData: flight,
            };
          };

          if (classes.length === 0) return [toCard(null, 0)];
          return classes.map((classStatus, classIndex) => toCard(classStatus, classIndex));
        });

        // Default: departure time so multiple same-day flights stay visible in order
        convertedFlights.sort((a, b) => a.departureTime.localeCompare(b.departureTime));
        setFlights(convertedFlights);
      } catch (error) {
        console.error('Error fetching flights:', error);
        setFlights([]);
        if (isFlightSearchLimitError(error)) {
          setLimitMessage(error.message);
        }
      } finally {
        setLoading(false);
      }
    };

    fetchFlights();
  }, [searchParams]);

  if (!searchParams) {
    return (
      <div className="min-h-screen bg-gray-50">
        <EmiratesHeader />
        <div className="container mx-auto px-4 py-20 text-center">
          <p className="text-xl text-gray-600 mb-6" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}>
            {t('flights.pleaseSearch')}
          </p>
          <button
            onClick={() => navigate('/')}
            className="bg-blue-900 hover:bg-blue-800 text-white font-bold px-8 py-3 rounded-lg transition-colors"
            style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}
          >
            {t('flights.backToHome')}
          </button>
        </div>
      </div>
    );
  }

  const originCity = cities.find(c => c.code === searchParams.origin);
  const destCity = cities.find(c => c.code === searchParams.destination);
  
  const getCityName = (city: typeof originCity) => {
    if (!city) return '';
    return language === 'en' ? city.name : city.nameFa;
  };

  const filteredFlights = flights.filter(flight => {
    if (filterStops === 'direct') return flight.stops === 0;
    if (filterStops === 'one') return flight.stops === 1;
    return true;
  });

  const sortedFlights = [...filteredFlights].sort((a, b) => {
    if (sortBy === 'price') return a.price - b.price;
    if (sortBy === 'duration') return a.duration.localeCompare(b.duration);
    if (sortBy === 'departure') return a.departureTime.localeCompare(b.departureTime);
    return 0;
  });

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-blue-50">
      <EmiratesHeader />
      
      {/* Hero Section */}
      <div className="bg-gradient-to-r from-blue-900 via-blue-800 to-blue-900 py-6 sm:py-12">
        <div className="container mx-auto px-4">
          <div className="max-w-6xl mx-auto">
            <h1 
              className="text-white text-2xl sm:text-4xl font-bold mb-3 sm:mb-4 text-center"
              style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}
            >
              {t('flights.searchResults')}
            </h1>
            <div className="bg-white/10 backdrop-blur-md rounded-lg p-4 sm:p-6 flex items-center justify-center gap-4 sm:gap-8 flex-wrap">
              <div className="flex items-center gap-2 text-white">
                <PaperAirplaneIcon className="w-5 h-5" />
                <span className="font-bold" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}>
                  {getCityName(originCity)} → {getCityName(destCity)}
                </span>
              </div>
              <div className="flex items-center gap-2 text-white">
                <ClockIcon className="w-5 h-5" />
                <span style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}>
                  {searchParams.departureDate}
                  {searchParams.returnDate && ` - ${searchParams.returnDate}`}
                </span>
              </div>
              <div className="flex items-center gap-2 text-white">
                <UserGroupIcon className="w-5 h-5" />
                <span style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}>
                  {typeof searchParams.passengers === 'number' 
                    ? `${searchParams.passengers} ${t('flights.passenger')}`
                    : (() => {
                        const p = searchParams.passengers;
                        const parts = [];
                        if (p?.adults) parts.push(`${p.adults} ${t('passengers.adult')}`);
                        if (p?.children) parts.push(`${p.children} ${t('passengers.child')}`);
                        if (p?.infants) parts.push(`${p.infants} ${t('passengers.infant')}`);
                        return parts.join(language === 'en' ? ', ' : '، ') || `1 ${t('flights.passenger')}`;
                      })()
                  }
                </span>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="container mx-auto px-4 sm:px-6 py-4 sm:py-8">
        <div className="max-w-6xl mx-auto">
          <div className="grid grid-cols-1 lg:grid-cols-4 gap-4 sm:gap-6">
            {/* Filters Sidebar */}
            <div className="lg:col-span-1">
              <div className="bg-white rounded-xl shadow-lg p-4 sm:p-6 sticky top-4">
                <h3 
                  className="text-lg sm:text-xl font-bold text-gray-900 mb-4 sm:mb-6 flex items-center gap-2"
                  style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}
                >
                  <AdjustmentsHorizontalIcon className="w-5 h-5 sm:w-6 sm:h-6" />
                  {t('flights.filters')}
                </h3>

                {/* Sort By */}
                <div className="mb-4 sm:mb-6">
                  <label className="block text-xs sm:text-sm font-bold text-gray-700 mb-2 sm:mb-3" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}>
                    {t('flights.sortBy')}
                  </label>
                  <div style={{ height: '42px' }}>
                    <CustomSelect
                      value={sortBy}
                      onChange={(value) => setSortBy(value as any)}
                      options={[
                        { value: 'price', label: t('flights.price') },
                        { value: 'duration', label: t('flights.duration') },
                        { value: 'departure', label: t('flights.departure') }
                      ]}
                      placeholder={t('flights.price')}
                    />
                  </div>
                </div>

                {/* Filter Stops */}
                <div>
                  <label className="block text-xs sm:text-sm font-bold text-gray-700 mb-2 sm:mb-3" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}>
                    {t('flights.stops')}
                  </label>
                  <div className="space-y-2">
                    <label className="flex items-center gap-2 cursor-pointer">
                      <input
                        type="radio"
                        name="stops"
                        checked={filterStops === 'all'}
                        onChange={() => setFilterStops('all')}
                        className="w-4 h-4 text-blue-900 focus:ring-blue-900"
                      />
                      <span style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}>{t('flights.allFlights')}</span>
                    </label>
                    <label className="flex items-center gap-2 cursor-pointer">
                      <input
                        type="radio"
                        name="stops"
                        checked={filterStops === 'direct'}
                        onChange={() => setFilterStops('direct')}
                        className="w-4 h-4 text-blue-900 focus:ring-blue-900"
                      />
                      <span style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}>{t('flights.directOnly')}</span>
                    </label>
                    <label className="flex items-center gap-2 cursor-pointer">
                      <input
                        type="radio"
                        name="stops"
                        checked={filterStops === 'one'}
                        onChange={() => setFilterStops('one')}
                        className="w-4 h-4 text-blue-900 focus:ring-blue-900"
                      />
                      <span style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}>{t('flights.oneStop')}</span>
                    </label>
                  </div>
                </div>
              </div>
            </div>

            {/* Flights List */}
            <div className="lg:col-span-3">
              {loading ? (
                <div className="text-center py-20">
                  <div className="inline-block animate-spin rounded-full h-12 w-12 border-b-4 border-blue-900"></div>
                  <p className="mt-4 text-gray-600" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}>
                    {t('flights.loadingFlights')}
                  </p>
                </div>
              ) : limitMessage ? (
                <div className="bg-white rounded-xl shadow-lg p-12 text-center">
                  <p className="text-xl text-gray-800" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}>
                    {limitMessage}
                  </p>
                </div>
              ) : sortedFlights.length === 0 ? (
                <div className="bg-white rounded-xl shadow-lg p-12 text-center">
                  <XMarkIcon className="w-16 h-16 text-gray-400 mx-auto mb-4" />
                  <p className="text-xl text-gray-600" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}>
                    {t('flights.noResults')}
                  </p>
                </div>
              ) : (
                <div className="space-y-4">
                  {sortedFlights.map((flight) => (
                    <div
                      key={flight.id}
                      className="bg-white rounded-xl shadow-lg hover:shadow-2xl transition-all duration-300 overflow-hidden border border-gray-200 hover:border-blue-300"
                    >
                      <div className="p-4 sm:p-6">
                        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between mb-4 gap-3">
                          <div className="flex items-center gap-3 sm:gap-4 min-w-0">
                            <div className="w-12 h-12 sm:w-16 sm:h-16 shrink-0 bg-gradient-to-br from-blue-900 to-blue-700 rounded-lg flex items-center justify-center">
                              <PaperAirplaneIcon className="w-6 h-6 sm:w-8 sm:h-8 text-white" />
                            </div>
                            <div className="min-w-0">
                              <h3 className="text-lg sm:text-xl font-bold text-gray-900 truncate" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}>
                                {flight.airline}
                              </h3>
                              <p className="text-sm text-gray-500" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}>
                                {flight.flightNumber}
                              </p>
                            </div>
                          </div>
                          <div className="text-right sm:text-left shrink-0" style={{ direction: language === 'en' ? 'ltr' : 'rtl' }}>
                            <div className="text-2xl sm:text-3xl font-bold text-blue-900" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}>
                              {language === 'en'
                                ? flight.price.toLocaleString('en-US')
                                : language === 'ar'
                                ? flight.price.toLocaleString('ar-SA')
                                : flight.price.toLocaleString('fa-IR')}
                            </div>
                            <div className="text-sm text-gray-500" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}>
                              {t('flights.currency')}
                            </div>
                          </div>
                        </div>

                        <div className="grid grid-cols-3 gap-1.5 sm:gap-4 mb-3 sm:mb-4 min-w-0">
                          <div className="text-center min-w-0 px-0.5">
                            <div className="text-base sm:text-2xl font-bold text-gray-900" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}>
                              {flight.departureTime}
                            </div>
                            {/* نمایش زمان واقعی اگر تأخیر داشته باشد */}
                            {flight.actualDepartureTime && flight.actualDepartureTime !== flight.departureTime && (
                              <div className="text-[10px] sm:text-xs text-orange-600 font-bold mt-1 break-words" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}>
                                ⏰ واقعی: {flight.actualDepartureTime}
                              </div>
                            )}
                            {/* نمایش تأخیر */}
                            {flight.delayMinutes && flight.delayMinutes > 0 && (
                              <div className="text-[10px] sm:text-xs text-red-600 font-bold mt-1 break-words" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}>
                                ⚠️ تأخیر: {flight.delayMinutes} دقیقه
                              </div>
                            )}
                            {/* نمایش گیت پرواز */}
                            {flight.departureGate && (
                              <div className="text-[10px] sm:text-xs text-blue-600 font-bold mt-1 break-words" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}>
                                🚪 گیت: {flight.departureGate}
                              </div>
                            )}
                            <div className="text-[10px] sm:text-sm text-gray-500 break-words leading-snug" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}>
                              {getCityName(originCity)}
                            </div>
                          </div>

                          <div className="flex flex-col items-center justify-center min-w-0 px-0.5">
                            <div className="text-[10px] sm:text-sm text-gray-500 mb-1" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}>
                              {flight.duration}
                            </div>
                            <div className="w-full h-0.5 bg-gray-300 relative">
                              <PaperAirplaneIcon className="w-3.5 h-3.5 sm:w-5 sm:h-5 text-blue-900 absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 rotate-90" />
                            </div>
                            <div className="text-[10px] sm:text-xs text-gray-400 mt-1 text-center" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}>
                              {flight.stops === 0 ? t('flights.noStops') : `${flight.stops} ${t('flights.stopsCount')}`}
                            </div>
                          </div>

                          <div className="text-center min-w-0 px-0.5">
                            <div className="text-base sm:text-2xl font-bold text-gray-900" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}>
                              {flight.arrivalTime}
                            </div>
                            {/* نمایش زمان واقعی فرود اگر تأخیر داشته باشد */}
                            {flight.actualArrivalTime && flight.actualArrivalTime !== flight.arrivalTime && (
                              <div className="text-[10px] sm:text-xs text-orange-600 font-bold mt-1 break-words" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}>
                                ⏰ واقعی: {flight.actualArrivalTime}
                              </div>
                            )}
                            {/* نمایش گیت فرود */}
                            {flight.arrivalGate && (
                              <div className="text-[10px] sm:text-xs text-blue-600 font-bold mt-1 break-words" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}>
                                🚪 گیت: {flight.arrivalGate}
                              </div>
                            )}
                            <div className="text-[10px] sm:text-sm text-gray-500 break-words leading-snug" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}>
                              {getCityName(destCity)}
                            </div>
                          </div>
                        </div>

                        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between pt-3 sm:pt-4 border-t border-gray-200 gap-3 sm:gap-0">
                          <div className="flex flex-col sm:flex-row items-start sm:items-center gap-2 sm:gap-4">
                            {(() => {
                              const saleCopy = getFlightSaleCopy(flight.saleState, language);
                              const badgeClass =
                                flight.saleState === 'cancelled'
                                  ? 'bg-red-100 text-red-800'
                                  : flight.saleState === 'bookable'
                                  ? 'bg-green-100 text-green-800'
                                  : 'bg-amber-100 text-amber-900';
                              return (
                                <>
                                  <div
                                    className={`px-2 sm:px-3 py-1 rounded-full text-xs sm:text-sm font-bold ${badgeClass}`}
                                    style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}
                                  >
                                    {saleCopy.badge}
                                  </div>
                                  {saleCopy.notice ? (
                                    <span
                                      className="text-xs sm:text-sm text-gray-600"
                                      style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}
                                    >
                                      {saleCopy.notice}
                                    </span>
                                  ) : null}
                                </>
                              );
                            })()}
                            {flight.availableSeats > 0 ? (
                              <div className="flex items-center gap-2 text-xs sm:text-sm text-gray-600">
                                <CheckCircleIcon className="w-4 h-4 sm:w-5 sm:h-5 text-green-600" />
                                <span style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}>
                                  {flight.availableSeats} {t('flights.availableSeatsRemaining')}
                                </span>
                              </div>
                            ) : null}
                            <div className="px-2 sm:px-3 py-1 bg-blue-100 text-blue-900 rounded-full text-xs sm:text-sm font-bold" style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif', direction: language === 'en' ? 'ltr' : 'rtl' }}>
                              {flight.class === 'economy' ? t('class.economy') : flight.class === 'business' ? t('class.business') : t('class.first')}
                            </div>
                          </div>
                          <button
                            type="button"
                            disabled={!flight.canBook}
                            onClick={() => {
                              if (!flight.canBook) return;
                              navigate(`/booking/details/${flight.id}`, {
                                state: {
                                  flight: {
                                    ...flight,
                                    origin: originCity?.name || flight.origin,
                                    destination: destCity?.name || flight.destination,
                                  },
                                },
                              });
                            }}
                            className={`w-full sm:w-auto font-bold px-4 sm:px-8 py-2 sm:py-3 rounded-lg transition-all flex items-center justify-center gap-2 text-sm sm:text-base ${
                              flight.canBook
                                ? 'bg-blue-900 hover:bg-blue-800 text-white transform hover:scale-105 shadow-lg hover:shadow-xl'
                                : 'bg-gray-300 text-gray-600 cursor-not-allowed'
                            }`}
                            style={{ fontFamily: 'DigiHamishe, DigiHamisheBold, sans-serif' }}
                          >
                            {getFlightSaleCopy(flight.saleState, language).cta}
                            {flight.canBook ? <ArrowRightIcon className="w-4 h-4 sm:w-5 sm:h-5" /> : null}
                          </button>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default FlightResultsPage;

